// variable
var header = $("header"),
	body = $("body"),
	backdrop = $(".backdrop"),
	toggleBackdrop = $(".toggle-backdrop"),
	backToTop = $(".back-to-top"),
	buttonMenu = $("#buttonMenu"),
	mobileWrap = $(".mobile-wrap"),
	buttonSearch = $("header .button-search"),
	buttonLanguage = $("header .button-language .toggle-language"),
	searchWrap = $(".search-wrap"),
	heightHeader = $("header").height(),
	heightWindow = $(window).height(),
	widthWindow = $(window).width(),
	outerHeightWindow = $(window).outerHeight();

// toggleText
$.fn.extend({
	toggleText: function (a, b) {
		return this.text(this.text() == b ? a : b);
	},
});

var APP = {
	fixed: () => {
		// header
		$(window).scrollTop() > heightHeader
			? header.addClass("active")
			: header.removeClass("active");
		$(window).scrollTop() > (outerHeightWindow - heightHeader)
			? backToTop.addClass("active")
			: backToTop.removeClass("active");
	},
	backdrop: () => {
		backdrop.on('click', function () {
			$(this).removeClass('open');
			toggleBackdrop.removeClass('open');
			body.removeClass('overflow-hidden');
			mobileWrap.removeClass('open');
			searchWrap.removeClass('open');
			$('.box-filter').removeClass('open');
		})
	},
	backToTop: () => {
		backToTop.on('click', function () {
			$('html, body').animate({ scrollTop: 0 }, 500);
		})
	},
	mapping: () => {
		let mainMenuLeft = $(".header-left .navbar-nav").mapping({
			mobileWrapper: ".mobile-wrap .navbar-nav-list",
			mobileMethod: "prependTo",
			desktopWrapper: ".header-left",
			desktopMethod: "prependTo",
			breakpoint: 1279.98,
		});
		let mainMenuRight = $(".header-right .navbar-nav").mapping({
			mobileWrapper: ".mobile-wrap .navbar-nav-list",
			mobileMethod: "appendTo",
			desktopWrapper: ".header-right",
			desktopMethod: "prependTo",
			breakpoint: 1279.98,
		});
		let buttonSearch = $("header .button-search").mapping({
			mobileWrapper: ".header-left",
			mobileMethod: "appendTo",
			desktopWrapper: ".header-right .button-phone",
			desktopMethod: "insertBefore",
			breakpoint: 1279.98,
		});
	},
	toggleDropdown: () => {
		var dropdownToggle = $(".dropdown-toggle"),
			dropdownMenu = $(".dropdown-menu");
		// Additional code to close the popup by clicking anywhere outside it
		$(document).on('click', function (e) {
			if (!$(e.target).closest('.dropdown').length) {
				$('.dropdown .dropdown-menu').slideUp();
			}
		});
	},
	toggleMenuMobile: () => {
		buttonMenu.on('click', function () {
			$(this).toggleClass('open');
			mobileWrap.toggleClass('open');
			backdrop.toggleClass('open');
		});
		// Additional code to close the popup by clicking anywhere outside it
		$(document).on('click', function (e) {
			if (!$(e.target).closest('.mobile-wrap').length && !$(e.target).closest('#buttonMenu').length) {
				buttonMenu.removeClass('open');
				mobileWrap.removeClass('open');
			}
		});
	},
	toggleLanguage: () => {
		buttonLanguage.on('click', function () {
			$(this).parents('.button-language').toggleClass('open');
		});
		// Additional code to close the popup by clicking anywhere outside it
		$(document).on('click', function (e) {
			if (!$(e.target).closest('.button-language').length) {
				$('.button-language').removeClass('open');
			}
		});
	},
	toggleSearch: () => {
		buttonSearch.on('click', function () {
			searchWrap.addClass('open');
			$('.searchbox input').focus();
		});
		// Additional code to close the popup by clicking anywhere outside it
		$(document).on('click', function (e) {
			if (!$(e.target).closest('.searchbox').length && !$(e.target).closest('.button-search').length) {
				searchWrap.removeClass('open');
			}
		});
	},
	init: () => {
		APP.backdrop();
		APP.backToTop();
		APP.mapping();
		APP.toggleDropdown();
		APP.toggleLanguage();
		APP.toggleMenuMobile();
		APP.toggleSearch();
	}
}

