function productInit(){
	// filter product
	$('.filter-block .filter-block-toggle').on('click', function () {
		$(this).parents('.filter-block').toggleClass('active').find('.filter-block-body').slideToggle();
	});

	// check all checkbox parent
	$('.filter-block .filter-block-head input[type="checkbox"]').on('click', function () {
		$(this).parents('.filter-block').find('.filter-block-body .filter-item input').prop('checked', $(this).prop('checked'));
	});

	// check all checkbox child
	$('.filter-block .filter-block-body .filter-item input').on('click', function () {
		var allChecked = true;

		$(this).parents('.filter-block').find('.filter-block-body .filter-item input').each(function () {
			if (!$(this).prop('checked')) {
				allChecked = false;
			}
		});

		$(this).parents('.filter-block').find('.filter-block-head input[type="checkbox"]').prop('checked', allChecked);
	});

	// open filter
	$('.btn-filter-open').on('click', function (e) {
		e.preventDefault();
		$('.box-filter').addClass('open');
		body.addClass('overflow-hidden');
		backdrop.addClass('open');
	});

	// close filter
	$('.btn-filter-close').on('click', function () {
		$('.box-filter').removeClass('open');
		body.removeClass('overflow-hidden');
		backdrop.removeClass('open');
	});

	$(document).on('click', function (e) {
		if (!$(e.target).closest('.box-filter').length && !$(e.target).closest('.btn-filter-open').length) {
			$('.box-filter').removeClass('open');
			body.removeClass('overflow-hidden');
			backdrop.removeClass('open');
		}
	});
}

function onChangeVariable(){
	$('.thwvsf_fields .thwvsf-rad-li .th-label-radio .thwvsf-rad').on('change', function () {
		var value = $(this).val();
		var slideIndex = $('.product-detail-top .swiper-slide').filter(function () {
			return $(this).hasClass(value)
		}).index();
		proDtTop.slideTo(slideIndex);
	});
}

function loadMore(){
	$('.load-more-list').each(function () {
		var dataShow = $(this).data('show-more');
		$(this).find('.load-more-item').slice(0, dataShow).show();
	});
	$('.load-more-button').on('click', function (e) {
		e.preventDefault();
		var dataLoad = $(this).data('load-more');
		var $itemHidden = $(this).parents('.box-load-more').find('.load-more-item:hidden');
		$itemHidden.slice(0, dataLoad).slideDown();
		var $newItemHidden = $(this).parents('.box-load-more').find('.load-more-item:hidden');
		if ($newItemHidden.length == 0) {
			$(this).hide();
		}
	});
}
